/* Все регионы РК: 3 города республиканского значения + 17 областей */
const REGION_KEYS=Array.from({length:20},(_,i)=>'reg'+String(i+1).padStart(2,'0'));

/* Телефон: всегда начинается с "+7 ", формат +7 7XX XXX XX XX */
function phoneDigits(v){
  let d=String(v||'').replace(/^\s*\+?7\s?/,'').replace(/\D/g,'');
  if(d.length>10 && /^[78]/.test(d)) d=d.slice(1);
  d=d.replace(/^8/,''); /* привычная «8» в начале номера — отбрасываем */
  return d.slice(0,10);
}
function formatPhone(d){
  let out='+7 ';
  if(d.length) out+=d.slice(0,3);
  if(d.length>3) out+=' '+d.slice(3,6);
  if(d.length>6) out+=' '+d.slice(6,8);
  if(d.length>8) out+=' '+d.slice(8,10);
  return out;
}
function initPhone(){
  const el=document.getElementById('rgPhone'); if(!el||el.dataset.ph)return;
  el.dataset.ph='1';
  const toEnd=()=>{const n=el.value.length; try{el.setSelectionRange(n,n)}catch(e){}};
  el.addEventListener('input',()=>{ el.value=formatPhone(phoneDigits(el.value)); });
  el.addEventListener('focus',()=>{ if(!el.value.startsWith('+7 ')) el.value=formatPhone(phoneDigits(el.value)); setTimeout(toEnd,0); });
  el.addEventListener('keydown',e=>{
    const start=el.selectionStart, end=el.selectionEnd;
    if((e.key==='Backspace'&&start<=3&&end<=3)||(e.key==='Delete'&&start<3)) e.preventDefault();
  });
  el.addEventListener('click',()=>{ if(el.selectionStart<3) toEnd(); });
  el.value=formatPhone(phoneDigits(el.value));
}

