/* Список «Населенный пункт» зависит от выбранного региона */
function fillCities(keepVal){
  const rk=document.getElementById('rgRegion').value, c=document.getElementById('rgCity');
  const other=document.getElementById('rgCityOther');
  const P=REGION_PLACES[rk], li=LANG==='kz'?1:0;
  if(!P){
    c.innerHTML=`<option value="">${t('o_c0')}</option>`; c.disabled=true; other.style.display='none'; return;
  }
  const opt=(arr,pre)=>arr.map((x,i)=>`<option value="${pre}${i}">${x[li]}</option>`).join('');
  c.innerHTML=`<option value="" disabled>${t('o_c1')}</option>`+
    (P.c.length?`<optgroup label="${t('o_cg1')}">${opt(P.c,'c')}</optgroup>`:'')+
    `<optgroup label="${t('o_cg2')}">${opt(P.d,'d')}</optgroup>`+
    `<option value="other">${t('o_c2')}</option>`;
  c.disabled=false; c.value=keepVal||''; if(!c.value) c.selectedIndex=0;
  other.style.display=c.value==='other'?'block':'none';
}
function initCity(){
  const r=document.getElementById('rgRegion'), c=document.getElementById('rgCity');
  if(r.dataset.ci)return; r.dataset.ci='1';
  r.addEventListener('change',()=>{ document.getElementById('rgCityOther').value=''; fillCities(''); });
  c.addEventListener('change',()=>{
    const o=document.getElementById('rgCityOther');
    o.style.display=c.value==='other'?'block':'none'; if(c.value==='other') o.focus();
  });
}

function fillSelects(){
  const r=document.getElementById('rgRegion'), p=document.getElementById('rgPriv');
  const keep=r.value;
  r.innerHTML=`<option value="" disabled>${t('o_r0')}</option>`+
    REGION_KEYS.map(k=>`<option value="${k}">${t(k)}</option>`).join('');
  r.value=keep||''; if(!r.value) r.selectedIndex=0;
  fillCities(document.getElementById('rgCity').value);
  p.innerHTML=['o_p0','o_p1','o_p2','o_p3','o_p4','o_p5'].map(k=>`<option value="${k}">${t(k)}</option>`).join('');
}

function applyI18n(){
  document.documentElement.lang = LANG==='kz'?'kk':'ru';
  document.querySelectorAll('[data-i18n]').forEach(el=>{ if(el.classList.contains('picked'))return; el.textContent=t(el.dataset.i18n); });
  document.querySelectorAll('[data-i18n-ph]').forEach(el=>el.placeholder=t(el.dataset.i18nPh));
  document.querySelectorAll('.lang-switch [data-lang]').forEach(b=>b.classList.toggle('on',b.dataset.lang===LANG));
  fillSelects(); initPhone(); initCity();
  updateSyncNote();
  if(me()) renderAll();
}
function setLang(l){ LANG=l; try{ localStorage.setItem('agz_lang',l) }catch(e){} applyI18n() }

/* ================= Вход / регистрация ================= */
function mode(m){
  const isL = m==='login';
  PENDING_ID=null;
  document.getElementById('authTabs').style.display='flex';
  document.getElementById('paneLogin').style.display=isL?'block':'none';
  document.getElementById('paneEds').style.display='none';
  document.getElementById('paneReg').style.display=isL?'none':'block';
  document.getElementById('tbLogin').classList.toggle('active',isL);
  document.getElementById('tbReg').classList.toggle('active',!isL);
  document.getElementById('authWrap').classList.toggle('wide',!isL);
}

function enter(id){
  MYID=id;
  const a=me(); LASTN=(a.notes||[]).length;
  document.getElementById('loginScreen').style.display='none';
  document.getElementById('app').style.display='block';
  renderAll();
  go(location.hash==='#docs'?'docs':'me');
}
function doLogin(){
  const iin=document.getElementById('lgIin').value.trim(), pin=document.getElementById('lgPin').value.trim();
  const err=document.getElementById('lgErr');
  if(!iin||!pin){err.textContent=t('lg_e1');return}
  const a=STORE.byIin(iin);
  if(!a){err.textContent=t('lg_e2');return}
  if(a.pin!==pin){err.textContent=t('lg_e3');return}
  err.textContent=''; goEdsStep(a.id);
}

/* --- Шаг 2 входа: подтверждение личности ключом ЭЦП --- */
function edsPicked(input,spanId){
  const f=input.files[0]; if(!f)return;
  const sp=document.getElementById(spanId);
  sp.textContent='🔑 '+f.name; sp.title=f.name; sp.classList.add('picked');
}
function goEdsStep(id){
  PENDING_ID=id;
  document.getElementById('authTabs').style.display='none';
  document.getElementById('paneLogin').style.display='none';
  document.getElementById('paneReg').style.display='none';
  document.getElementById('paneEds').style.display='block';
  document.getElementById('lgEdsFile').value='';
  { const sp=document.getElementById('lgEdsName'); sp.textContent=t('eds_pick'); sp.title=''; sp.classList.remove('picked'); }
  document.getElementById('lgEdsPass').value='';
  document.getElementById('edsErr').textContent='';
}
function backToLoginStep1(){
  document.getElementById('lgPin').value='';
  mode('login');
}
function doLoginEds(){
  const errEl=document.getElementById('edsErr');
  const a=STORE.find(PENDING_ID);
  if(!a){errEl.textContent=t('lg_e2');mode('login');return}
  const file=document.getElementById('lgEdsFile').files[0];
  const pass=document.getElementById('lgEdsPass').value.trim();
  if(!file||!pass){errEl.textContent=t('lg_e4');return}
  if(!/\.(p12|pfx)$/i.test(file.name)){errEl.textContent=t('lg_e5');return}
  if(!a.eds||pass!==a.eds.pass){errEl.textContent=t('lg_e6');return}
  errEl.textContent='';
  const id=PENDING_ID; PENDING_ID=null;
  toast(t('toast_eds_ok'));
  enter(id);
}
function doReg(){
  const err=document.getElementById('rgErr');
  const fio=document.getElementById('rgFio').value.trim();
  const iin=document.getElementById('rgIin').value.trim();
  const pin=document.getElementById('rgPin').value.trim();
  const edsFile=document.getElementById('rgEdsFile').files[0];
  const edsPass=document.getElementById('rgEdsPass').value.trim();
  if(!fio||!iin||!pin){err.textContent=t('rg_e1');return}
  if(!/^\d{12}$/.test(iin)){err.textContent=t('rg_e2');return}
  if(STORE.byIin(iin)){err.textContent=t('rg_e3');return}
  if(!edsFile||!edsPass){err.textContent=t('rg_e4');return}
  if(!/\.(p12|pfx)$/i.test(edsFile.name)){err.textContent=t('rg_e5');return}
  const rk=document.getElementById('rgRegion').value, pk=document.getElementById('rgPriv').value;
  if(!rk){err.textContent=t('rg_e6');return}
  const phD=phoneDigits(document.getElementById('rgPhone').value);
  if(phD.length>0 && phD.length<10){err.textContent=t('rg_e7');return}
  const reg={ru:I18N.ru[rk],kz:I18N.kz[rk]}, prv={ru:I18N.ru[pk],kz:I18N.kz[pk]};
  const dobRaw=document.getElementById('rgDob').value;
  const dob=dobRaw?dobRaw.split('-').reverse().join('.'):'—';
  const cv=document.getElementById('rgCity').value;
  let city;
  if(cv==='other'){
    const txt=document.getElementById('rgCityOther').value.trim();
    if(!txt){err.textContent=t('rg_e9');return}
    city={ru:txt,kz:txt};
  } else if(cv){
    const x=REGION_PLACES[rk][cv[0]][+cv.slice(1)]; city={ru:x[0],kz:x[1]};
  } else {err.textContent=t('rg_e8');return}
  const id=STORE.nextId();
  const docs={}; DOC_TYPES.forEach(d=>docs[d.id]={s:'none'});
  const rec={ id, iin, pin, seen:false,
    fio:{ru:fio,kz:fio}, dob, region:reg, city,
    phone:phD.length===10?formatPhone(phD):'—', sex:'',
    ent:Number(document.getElementById('rgEnt').value)||0,
    eds:{file:edsFile.name, pass:edsPass},
    priv:prv, submitted:null, status:'draft', docs,
    log:[], notes:[{txt:{ru:I18N.ru.n_reg,kz:I18N.kz.n_reg},dt:stamp(),n:1}] };
  STORE.mutate(db=>{ db.applicants.push(rec) });
  err.textContent=''; toast(t('toast_reg')); enter(id);
}

function logout(){
  MYID=null;
  document.getElementById('app').style.display='none';
  document.getElementById('loginScreen').style.display='block';
  document.getElementById('lgIin').value='';document.getElementById('lgPin').value='';
  mode('login');
  toast(t('toast_bye'));
}

/* ================= Навигация ================= */
function go(p){
  document.querySelectorAll('#app .tab').forEach(s=>s.classList.toggle('active',s.id===p));
  document.querySelectorAll('#nav button[data-p]').forEach(b=>{ b.classList.toggle('active',b.dataset.p===p); if(b.dataset.p===p&&typeof centerTab==='function') centerTab(b) });
  if(p==='news'&&me()){ LASTN=(me().notes||[]).length; document.getElementById('newsDot').style.display='none' }
  const top=document.getElementById('app').getBoundingClientRect().top+window.scrollY-110;
  if(window.scrollY>top) window.scrollTo({top,behavior:'smooth'});
}
document.getElementById('nav').addEventListener('click',e=>{
  const b=e.target.closest('button[data-p]'); if(b)go(b.dataset.p);
});

/* ================= Рендер ================= */
const BLBL={ok:'b_ok',review:'b_wait',fix:'b_fix',none:'b_none'};

function renderAll(){ if(!me())return; renderUser();renderMe();renderDocs();renderNews();renderStages();renderProfile() }

function renderUser(){
  const a=me(), fio=L(a.fio);
  document.getElementById('ubAva').textContent=initials(fio);
  document.getElementById('ubName').textContent=fio;
  document.getElementById('ubCase').textContent=a.id;
  document.getElementById('ubIin').textContent=a.iin;
  document.getElementById('ubStatus').innerHTML=`<span class="badge ${APP_BADGE[a.status]||'review'}">${t('st_'+a.status)}</span>`;
}

function renderMe(){
  const a=me(), an=analyze(a);
  const conf={
    draft:['📝','','v_draft_h','v_draft_p'],
    review:['⏳','','v_review_h','v_review_p'],
    fix:['⚠️','bad','v_fix_h','v_fix_p'],
    approved:['✅','ok','v_ok_h','v_ok_p'],
    rejected:['⛔','bad','v_rej_h','v_rej_p']}[a.status];
  document.getElementById('verdictCard').className='card verdict '+conf[1];
  document.getElementById('vIc').textContent=conf[0];
  document.getElementById('vTitle').textContent=t(conf[2]);
  document.getElementById('vText').textContent=t(conf[3]);

  /* кнопка отправки заявки в комиссию */
  const act=document.getElementById('vAct'); act.innerHTML='';
  if(a.status==='draft'||a.status==='fix'){
    const ready=an.filled;
    act.innerHTML=`<button class="btn mt-2" ${ready?'':'disabled'} onclick="submitApp()">
        ${a.status==='draft'?t('btn_send'):t('btn_resend')} <span class="arrow">→</span></button>
      ${ready?'':`<div class="alert warn mt-1"><span>⚠️</span><div>${t('send_block')}</div></div>`}`;
  } else if((a.notes||[]).length){
    act.innerHTML=`<button class="btn btn--outline btn--sm mt-1" onclick="go('news')">${t('me_news_open')}</button>`;
  }

  document.getElementById('kOk').textContent=an.ok;
  document.getElementById('kWait').textContent=an.review;
  document.getElementById('kFix').textContent=an.fix;
  const draft=a.status==='draft', up=an.total-an.none;
  const shown=draft?Math.round(up/an.total*100):an.pct;
  document.getElementById('progIn').style.width=shown+'%';
  document.getElementById('progPct').textContent=shown+'%';
  document.getElementById('progTxt').textContent=t(draft?'pr_txt2':'pr_txt').replace('{a}',draft?up:an.ok).replace('{b}',an.total);

  let mb='';
  if(an.missing.length)mb+=`<div class="alert warn"><span>📎</span><div><b>${t('miss_h')}</b><br>${an.missing.map(d=>'• '+L(d)).join('<br>')}</div></div>`;
  if(an.broken.length)mb+=`<div class="alert danger"><span>✏️</span><div><b>${t('broken_h')}</b><br>${an.broken.map(d=>'• '+L(d)).join('<br>')}</div></div>`;
  const box=document.getElementById('missBox'); box.innerHTML=mb; box.style.marginTop=mb?'16px':'0';

  const ul=document.getElementById('todoList');ul.innerHTML='';
  const tasks=[];
  DOC_TYPES.filter(d=>d.req).forEach(d=>{
    const s=(a.docs[d.id]||{s:'none'}).s;
    if(s==='none')tasks.push({c:'',x:t('todo_up').replace('{n}',L(d))});
    else if(s==='fix')tasks.push({c:'',x:t('todo_fix').replace('{n}',L(d))});
    else if(s==='review'&&a.status!=='draft')tasks.push({c:'done',x:t('todo_wait').replace('{n}',L(d))});
  });
  if((a.status==='draft'||a.status==='fix')&&an.filled)tasks.unshift({c:'',x:t('todo_send')});
  if(!tasks.length)tasks.push({c:'done',x:t('todo_none')});
  tasks.forEach(o=>{const li=document.createElement('li');li.className=o.c;li.textContent=o.x;ul.appendChild(li)});
}

function renderDocs(){
  const a=me();
  const fr=document.getElementById('docFilter');fr.innerHTML='';
  [['all','f_all'],['ok','f_ok'],['review','f_wait'],['fix','f_fix'],['none','f_none']].forEach(([k,lbl])=>{
    const b=document.createElement('button');b.className='fchip'+(k===DOC_F?' on':'');
    b.textContent=t(lbl);b.onclick=()=>{DOC_F=k;renderDocs()};fr.appendChild(b);
  });
  const box=document.getElementById('docList');box.innerHTML='';
  docsOf(a).filter(({v})=>DOC_F==='all'||v.s===DOC_F).forEach(({t:d,v})=>{
    const c=document.createElement('div');c.className='doc-card s-'+v.s;
    const hint=LANG==='kz'?d.hkz:d.hru, cmt=L(v.c);
    let act='';
    if(v.s==='none')act=`<div class="dc-act"><button class="btn btn--sm" onclick="upload('${d.id}')">📤 ${t('dc_upload')}</button></div>`;
    else if(v.s==='fix')act=`<div class="dc-act"><button class="btn btn--sm" onclick="upload('${d.id}')">🔁 ${t('dc_replace')}</button></div>`;
    else if(v.s==='ok')act=`<div class="locked">${t('dc_lock')}</div>`;
    else act= a.status==='draft'
      ? `<div class="dc-act"><button class="btn btn--outline btn--sm" onclick="upload('${d.id}')">${t('dc_replace')}</button></div>`
      : `<div class="locked">${t('dc_locked_wait')}</div>`;

    /* --- проверка сертификата ЕНТ по базе (только d5, сразу после загрузки файла) --- */
    let ent='';
    if(d.id==='d5' && v.s!=='none'){
      if(v.entCheck==='ok'){
        const mism = v.entScore!=null && a.ent && Number(a.ent)!==Number(v.entScore);
        ent=`<div class="ent-box ent-ok"><b>${t('ent_ok')}</b> · №${esc(v.entNum)} · ${t('ent_score')}: ${v.entScore}
             ${mism?`<div class="ent-warn">${t('ent_mismatch')}</div>`:''}
             ${v.s!=='ok'?`<br><button class="lnk" onclick="resetEntCheck('${d.id}')">${t('ent_recheck')}</button>`:''}</div>`;
      } else if(v.entCheck==='fake'){
        ent=`<div class="ent-box ent-fake"><b>${t('ent_fake')}</b> · №${esc(v.entNum)}
             ${v.s!=='ok'?`<br><button class="lnk" onclick="resetEntCheck('${d.id}')">${t('ent_recheck')}</button>`:''}</div>`;
      } else if(v.s!=='ok'){
        ent=`<div class="ent-box ent-pend">
             <label>${t('ent_label')}</label>
             <div style="display:flex;gap:8px;flex-wrap:wrap">
               <input id="entNum_${d.id}" placeholder="0000000000" maxlength="12" inputmode="numeric" style="flex:1;min-width:150px">
               <button class="btn btn--sm" onclick="checkEntCert('${d.id}')">${t('ent_check_btn')}</button>
             </div></div>`;
      }
    }

    c.innerHTML=`
      <div class="dc-top">
        <span class="dc-name">${L(d)}</span>
        <span class="dc-req ${d.req?'':'opt'}">${d.req?t('req'):t('opt')}</span>
        <span class="dc-badge"><span class="badge ${DOC_BADGE[v.s]}">${t(BLBL[v.s])}</span></span>
      </div>
      ${hint?`<div class="dc-hint">${hint}</div>`:''}
      ${v.f?`<div class="dc-file">📄 <b>${esc(v.f)}</b>${v.size?' · '+fsize(v.size):''} · ${v.dt}
             ${v.fid?`<button class="lnk" onclick="openFile('${v.fid}')">${t('dc_view')}</button>`:''}</div>`:''}
      ${ent}
      ${cmt?`<div class="dc-cmt ${v.s==='ok'?'ok':''}"><b>${t('dc_cmt')}</b> ${esc(cmt)}</div>`:''}
      ${act}`;
    box.appendChild(c);
  });
  if(!box.children.length) box.innerHTML=`<div class="card empty">—</div>`;
}

/* --- РЕАЛЬНАЯ ЗАГРУЗКА ФАЙЛА --- */
let PICK=null;
function upload(id){
  PICK=id;
  const inp=document.getElementById('filePick');
  inp.value=''; inp.click();
}
document.getElementById('filePick').addEventListener('change',async e=>{
  const file=e.target.files[0]; if(!file||!PICK)return;
  const id=PICK; PICK=null;
  const okType = ALLOWED.includes(file.type) || /\.(pdf|jpe?g|png|webp|docx?|zip)$/i.test(file.name);
  if(!okType){ toast(t('e_type')); return }
  if(file.size>MAX_FILE){ toast(t('e_size')); return }
  const fid = MYID+'_'+id+'_'+Date.now();
  const old = (me().docs[id]||{}).fid;
  try{ await FILES.put(fid,file) }catch(err){ toast(t('e_save')); return }
  if(old) FILES.del(old);
  STORE.mutate(db=>{
    const a=db.applicants.find(x=>x.id===MYID);
    a.docs[id]={s:'review', f:file.name, size:file.size, mime:file.type, fid, dt:today()};
  });
  toast(t('toast_up')); renderAll();
});

/* --- сверка сертификата ЕНТ с базой (документ d5) --- */
function checkEntCert(id){
  const input=document.getElementById('entNum_'+id);
  const num=input.value.trim();
  if(!/^\d{6,12}$/.test(num)){ toast(t('e_ent_fmt')); return }
  const found=ENT_REGISTRY.find(r=>r.num===num);
  STORE.mutate(db=>{
    const a=db.applicants.find(x=>x.id===MYID);
    const v=a.docs[id]||{s:'review'};
    a.docs[id]={...v, entNum:num, entCheck:found?'ok':'fake', entScore:found?found.score:null, entDt:stamp()};
  });
  toast(found?t('toast_ent_ok'):t('toast_ent_fake'));
  renderDocs();
}
function resetEntCheck(id){
  STORE.mutate(db=>{
    const a=db.applicants.find(x=>x.id===MYID);
    const v=a.docs[id]||{s:'review'};
    a.docs[id]={...v, entNum:null, entCheck:null, entScore:null};
  });
  renderDocs();
}

/* --- просмотр загруженного файла --- */
async function openFile(fid){
  const rec=await FILES.get(fid); if(!rec)return;
  const url=URL.createObjectURL(rec.blob);
  document.getElementById('pvName').textContent=rec.name;
  document.getElementById('pvMeta').textContent=fsize(rec.size);
  const dl=document.getElementById('pvDl'); dl.href=url; dl.setAttribute('download',rec.name);
  const body=document.getElementById('pvBody');
  if(/^image\//.test(rec.type||'')) body.innerHTML=`<img src="${url}" alt="">`;
  else if((rec.type||'')==='application/pdf'||/\.pdf$/i.test(rec.name)) body.innerHTML=`<iframe src="${url}"></iframe>`;
  else body.innerHTML=`<div class="pv-non">${t('pv_no')}</div>`;
  document.getElementById('pv').classList.add('on');
}
function closePv(e){
  if(e&&e.type==='click'&&e.target&&e.target.closest&&e.target.closest('.pv-box'))return;
  document.getElementById('pv').classList.remove('on');
  document.getElementById('pvBody').innerHTML='';
}
document.addEventListener('keydown',e=>{ if(e.key==='Escape') closePv() });

/* --- ОТПРАВКА ЗАЯВКИ В КОМИССИЮ --- */
function submitApp(){
  const a=me(), an=analyze(a);
  if(!an.filled){toast(t('send_block'));return}
  const first = a.status==='draft';
  SELF=true;
  STORE.mutate(db=>{
    const r=db.applicants.find(x=>x.id===MYID);
    r.status='review'; r.seen=false;
    if(!r.submitted) r.submitted=today();
    r.notes.unshift({txt:{ru:first?I18N.ru.n_sent:I18N.ru.n_resent, kz:first?I18N.kz.n_sent:I18N.kz.n_resent},dt:stamp(),n:1});
    r.log.unshift({txt:{ru:first?'заявка подана абитуриентом':'абитуриент отправил исправления',
                        kz:first?'талапкер өтінім берді':'талапкер түзетулерді жіберді'},dt:stamp()});
    db.log.unshift({txt:{ru:`${r.id} — ${first?'поступила новая заявка':'поступлены исправленные документы'}`,
                         kz:`${r.id} — ${first?'жаңа өтінім түсті':'түзетілген құжаттар түсті'}`},dt:stamp()});
  });
  SELF=false;
  LASTN=(me().notes||[]).length;
  toast(first?t('toast_sent'):t('toast_resent')); renderAll();
}

function renderNews(){
  const a=me(), box=document.getElementById('newsList');
  const ns=a.notes||[];
  box.innerHTML=ns.length?ns.map(n=>`<div class="note-item"><div class="nico">🔔</div><div>${esc(L(n.txt))}<br><small>${n.dt}</small></div></div>`).join('')
    :`<div class="empty">${t('nw_empty')}</div>`;
  document.getElementById('newsDot').style.display = ns.length>LASTN ? 'inline-block' : 'none';
}

function renderStages(){
  const a=me(), an=analyze(a);
  const box=document.getElementById('stepList');box.innerHTML='';
  const stages=a.stages||{};
  STAGES.forEach((s,i)=>{
    const d=document.createElement('div');
    let cls,note;
    if(i===0){
      /* s1 — приём документов */
      if(a.status==='draft'){cls='wait';note=t('sg_s0')}
      else {cls='done';note=t('sg_s1').replace('{d}',a.submitted||'—')}
    } else if(i===1){
      /* s2 — проверка документов комиссией */
      if(a.status==='draft'){cls='wait';note=t('sg_lock')}
      else if(an.complete){cls='done';note=t('sg_done')}
      else {cls='now';note=t('sg_s2')}
    } else {
      /* s3..s7 — персональные этапы, решение принимает комиссия */
      const v=stages[s.id]||{s:'none'};
      const prevOk = i===2 ? an.complete : (stages[STAGES[i-1].id]||{s:'none'}).s==='ok';
      if(v.s==='ok'){cls='done';note=t('sg_done')}
      else if(v.s==='fix'){cls='fail';note=t('sg_fail').replace('{c}',esc(L(v.c))||'')}
      else if(prevOk){cls='now';note=t('sg_now')}
      else {cls='wait';note=t('sg_lock')}
    }
    d.className='route-step '+cls;
    d.innerHTML=`<b>${i+1}. ${L(s)}</b><span>${note}</span>`;
    box.appendChild(d);
  });
}

function renderProfile(){
  const a=me();
  const rows=[
    ['l_fio',L(a.fio),1],['l_case',a.id,0],['l_iin',a.iin,0],['l_dob',a.dob,0],
    ['l_phone',a.phone,0],['l_region',L(a.region),0],['l_city',L(a.city),0],
    ['l_ent',a.ent?String(a.ent):t('ent_no'),0],
    ['l_priv',L(a.priv),1],['l_sub',a.submitted||t('not_sent'),0]
  ];
  document.getElementById('anketa').innerHTML=rows.map(([k,v,full])=>
    `<div class="${full?'full':''}"><dt>${t(k)}</dt><dd>${esc(v)}</dd></div>`).join('');
}

function sendAppeal(){
  const i=document.getElementById('appealTxt');
  if(!i.value.trim()){toast(t('toast_ap_e'));return}
  const txt=i.value.trim();
  STORE.mutate(db=>{
    const a=db.applicants.find(x=>x.id===MYID);
    if(!a.appeals) a.appeals=[];
    a.appeals.unshift({txt, dt:stamp(), seen:false});
    a.log.unshift({txt:{ru:'обращение абитуриента: '+txt, kz:'талапкер өтініші: '+txt},dt:stamp()});
    db.log.unshift({txt:{ru:`${a.id} — обращение абитуриента`, kz:`${a.id} — талапкер өтініші`},dt:stamp()});
  });
  i.value='';toast(t('toast_ap'));
}

/* ============ ЖИВОЕ ОБНОВЛЕНИЕ ИЗ ПАНЕЛИ КОМИССИИ ============ */
STORE.onChange(()=>{
  if(!me()||SELF)return;
  const n=(me().notes||[]).length;
  if(n>LASTN) toast(t('toast_new'));
  renderAll();
});

/* Вход и регистрация — только после загрузки базы из облака,
   чтобы найти абитуриента, зарегистрированного на другом устройстве */
function withSync(fn){
  return async function(){
    if(STORE.cloud()==='connecting'){
      document.querySelectorAll('#paneLogin .btn, #paneReg .btn').forEach(b=>b.disabled=true);
      await STORE.ready();
      document.querySelectorAll('#paneLogin .btn, #paneReg .btn').forEach(b=>b.disabled=false);
    }
    return fn.apply(this,arguments);
  };
}
doLogin=withSync(doLogin); doReg=withSync(doReg);

