async function demoLogin(){
  try{ await STORE.ready() }catch(e){}
  let a=STORE.byIin(DEMO_IIN);
  if(!a){
    const rec=buildDemoRecord();
    STORE.mutate(db=>{ db.applicants.push(rec); db.log.unshift({txt:{ru:`${rec.id} — поступила новая заявка`,kz:`${rec.id} — жаңа өтінім түсті`},dt:stamp()}) });
    a=rec;
  }
  toast(t('toast_eds_ok'));
  enter(a.id);
}

